noise = (texture(sampler_pw_noise_lq,rss / 32.0)-.5 >= 0);
tmp = abs(fract(rss * 8.0)-.5);
dots += clamp01(.02/length(tmp)) * noise;
dots *= clamp01(.2/abs(rss0.y));
dots *= dots*.6;
//*************************
float z = q32/(uv1.y-.02);//floor proxy
float mask = clamp01(4.0 / z);
rs0.x = (uv1.x)*z;
rs0.y = z / 4.0;
